import json, pathlib
for n in (1,2,3):
  for layer in ('evaluated','coboundary'):
    p=pathlib.Path(f'data/C_{n}_{layer}.json')
    d=json.loads(p.read_text())
    print(f'\n{p}: root={type(d).__name__}, keys={list(d) if isinstance(d,dict) else len(d)}')
    if isinstance(d,dict):
      for k,v in d.items():
        if isinstance(v,(dict,list)):
          print(f'  {k}: {type(v).__name__} len={len(v)}')
          if isinstance(v,list) and v: print('   first=',repr(v[0])[:500])
          elif isinstance(v,dict) and v: print('   first=',repr(next(iter(v.items())))[:500])
        else: print(f'  {k}: {v!r}')
