import json,re

def vars_in(s): return sorted(set(re.findall(r'gb_[A-Za-z0-9_]+',s)))
for n in (1,2,3):
 g=json.load(open(f'data/C_{n}_gamma.json'))['inhomogeneous_deformation']['gamma_structure']
 c=json.load(open(f'data/C_{n}_coboundary.json'))['coboundary']['structure']
 ck={(x['X'],x['Y'],x['Z']) for x in c}
 miss=[x for x in g if (x['X'],x['Y'],x['Z']) not in ck]
 forced=set()
 for x in miss: forced.update(vars_in(x['coeff']))
 print(f'\nC{n}: gamma rows absent from coboundary support={len(miss)}, gb params touched={len(forced)}')
 for x in miss[:30]: print(x)
 print('forced vars:', sorted(forced))
PY

