 phis=c['odd_linear_map']['parameter_order']; gbvars=json.load(open(f'data/C_{n}_evaluated.json'))['gb_assignment']['parameter_order']
 keys=sorted({(x['X'],x['Y'],x['Z']) for x in g+cob}); rid={k:i for i,k in enumerate(keys)}; pi={v:i for i,v in enumerate(phis)}; gi={v:i for i,v in enumerate(gbvars)}
