from scipy.sparse.linalg import lsqr

def parse(s):
 out={}
 for sign,t in re.findall(r'([+-]?)([^+-]+)',s.replace(' ','')):
  q=-1 if sign=='-' else 1
  if '*' in t: a,v=t.split('*',1);a=Fraction(a)
  else:a,v=Fraction(1),t
  out[v]=out.get(v,Fraction())+q*a
 return {k:v for k,v in out.items() if v}
for n in (1,2,3):
 gamma=json.load(open(f'data/C_{n}_gamma.json'))['inhomogeneous_deformation']['gamma_structure']
 cb=json.load(open(f'data/C_{n}_coboundary.json'))
 cob=[t for t in cb['coboundary']['structure'] if t['Z']!='K']; gamma=[t for t in gamma if t['Z']!='K']
 phis=cb['odd_linear_map']['parameter_order']; gb=json.load(open(f'data/C_{n}_evaluated.json'))['gb_assignment']['parameter_order']
 keys=sorted({(t['X'],t['Y'],t['Z']) for t in cob+gamma}); ri={k:i for i,k in enumerate(keys)}; pi={v:i for i,v in enumerate(phis)}; gi={v:i for i,v in enumerate(gb)}
 Arows=[{} for _ in keys]; Grows=[{} for _ in keys]
 for t in cob:
  r=ri[(t['X'],t['Y'],t['Z'])]
  for v,c in parse(t['coeff']).items(): Arows[r][pi[v]]=c
 for t in gamma:
  r=ri[(t['X'],t['Y'],t['Z'])]
  for v,c in parse(t['coeff']).items(): Grows[r][gi[v]]=c
 rr=[];cc=[];vv=[]
 for r,row in enumerate(Arows):
  for col,val in row.items():rr.append(r);cc.append(col);vv.append(float(val))
 A=csr_matrix((vv,(rr,cc)),shape=(len(keys),len(phis)))
 ok=[]; maxden=0; nnzs=[]
 for j in range(len(gb)):
  b=np.zeros(len(keys))
  for r,row in enumerate(Grows): b[r]=float(row.get(j,0))
  x=lsqr(A,b,atol=1e-13,btol=1e-13,iter_lim=30000)[0]
  for lim in (100000,10000000,1000000000):
   q=[Fraction(float(y)).limit_denominator(lim) for y in x]
   residual=[]
   for r in range(len(keys)):
    val=sum(c*q[k] for k,c in Arows[r].items())-Grows[r].get(j,Fraction())
    if val: residual.append((r,val))
