  ok.append(not residual); maxden=max(maxden,max(v.denominator for v in q)); nnzs.append(sum(v!=0 for v in q))
 print(f'C{n}: exact rational verification for each of {len(gb)} gb basis vectors: {all(ok)}, nonzero phi counts={nnzs}, max denominator={maxden}')
