import json,re
from fractions import Fraction
import numpy as np
from scipy.sparse import csr_matrix
from scipy.sparse.linalg import lsqr

def terms(s):
 out={}
 for sign,t in re.findall(r'([+-]?)([^+-]+)',s.replace(' ','')):
  q=-1 if sign=='-' else 1
  if '*' in t: a,v=t.split('*',1); a=Fraction(a)
  else: a,v=Fraction(1),t
  out[v]=out.get(v,Fraction())+q*a
 return {k:v for k,v in out.items() if v}
for n in (1,2,3):
 d=json.load(open(f'data/C_{n}_evaluated.json')); g=json.load(open(f'data/C_{n}_gamma.json'))['inhomogeneous_deformation']['gamma_structure']; c=json.load(open(f'data/C_{n}_coboundary.json'))
 print(f'C{n}: evaluated gamma rows={len(d["inhomogeneous_deformation"]["gamma_structure"])}, K rows={sum(t["Z"]=="K" for t in d["inhomogeneous_deformation"]["gamma_structure"])}, non-K={sum(t["Z"]!="K" for t in d["inhomogeneous_deformation"]["gamma_structure"])}')
 cb=[t for t in c['coboundary']['structure'] if t['Z']!='K']; g=[t for t in g if t['Z']!='K']
 phis=c['odd_linear_map']['parameter_order']; gb=d['gb_assignment']['parameter_order']
 keys=sorted({(t['X'],t['Y'],t['Z']) for t in cb+g}); ri={k:i for i,k in enumerate(keys)}; pi={v:i for i,v in enumerate(phis)}
 ar=[];ac=[];av=[]
 for t in cb:
  r=ri[(t['X'],t['Y'],t['Z'])]
  for p,x in terms(t['coeff']).items():ar.append(r);ac.append(pi[p]);av.append(float(x))
 A=csr_matrix((av,(ar,ac)),shape=(len(keys),len(phis)))
 Gval=np.zeros(len(keys))
 for t in g:
  r=ri[(t['X'],t['Y'],t['Z'])]
  Gval[r]+=sum(float(v) for k,v in terms(t['coeff']).items())
 x=lsqr(A,Gval,atol=1e-13,btol=1e-13,iter_lim=30000)[0]
 q=[Fraction(float(v)).limit_denominator(1000000) for v in x]
 mismatch=[]
 for r in range(len(keys)):
  lhs=sum(terms(t['coeff']).get(phis[j],0)*q[j] for t in cb if ri[(t['X'],t['Y'],t['Z'])]==r)
  rhs=Fraction(int(round(Gval[r])))
  if lhs!=rhs:mismatch.append((keys[r],lhs,rhs))
 print('  all-ones exact solution:',not mismatch,'nonzero phi=',sum(v!=0 for v in q),'max denominator=',max(v.denominator for v in q))
 if n==1:
  print('  phi certificate (C1 all-ones):')
  for p,v in zip(phis,q):
   if v: print('   ',p,'=',v)
